def brand(root: str, site_name: str) -> str:
    """Header brand: the wordmark (light/dark files, one hidden by CSS) for the Madalean site, else mark + name."""
    if site_name == "Madalean":
        return (f'<img class="wordmark wm-light" src="{root}assets/wordmark.svg" alt="Madalean" width="122" height="36">'
                f'<img class="wordmark wm-dark" src="{root}assets/wordmark-dark.svg" alt="Madalean" width="122" height="36">')
    return f'{MARK}<span>{html.escape(site_name)}</span>'

